import{_ as t,o as s,c as o,a2 as r}from"./chunks/framework.BZO4qERu.js";const h=JSON.parse('{"title":"Maintaining the research workspace","description":"","frontmatter":{},"headers":[],"relativePath":"developers/architecture.md","filePath":"developers/architecture.md","lastUpdated":1792570296000}'),a={name:"developers/architecture.md"};function c(d,e,n,i,p,l){return s(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="maintaining-the-research-workspace" tabindex="-1">Maintaining the research workspace <a class="header-anchor" href="#maintaining-the-research-workspace" aria-label="Permalink to &quot;Maintaining the research workspace&quot;">​</a></h1><p>The Community package is the source of shared Python and Vue implementation. PaperSeek online builds on the same sources; deployment adapters must not copy algorithms or pages.</p><p>Shared UI tokens, layout rules, and stylesheet ownership are documented in the <a href="./design-system">interface guidelines</a>.</p><p>Python paths below are relative to <code>backend/src/</code>; Web paths are relative to the repository root.</p><table tabindex="0"><thead><tr><th>Responsibility</th><th>Location</th></tr></thead><tbody><tr><td>Compact native metadata and document identity</td><td><code>paperseek_core/bibliometrics/corpus.py</code></td></tr><tr><td>Distributions and coverage</td><td><code>paperseek_core/bibliometrics/statistics.py</code></td></tr><tr><td>Bounded sparse networks</td><td><code>paperseek_core/bibliometrics/networks.py</code></td></tr><tr><td>Create/read/export/delete analysis use cases</td><td><code>paperseek_app/bibliometrics/services.py</code></td></tr><tr><td>Storage contract and small record models</td><td><code>paperseek_app/bibliometrics/ports.py</code>, <code>models.py</code></td></tr><tr><td>Community persistence and HTTP composition</td><td><code>paperseek_community/persistence/sqlite_bibliometrics.py</code>, <code>api_routes/bibliometrics.py</code></td></tr><tr><td>Navigation, menus, module history</td><td><code>web/src/features/workspace/</code></td></tr><tr><td>Analysis views, controls, browser layout worker</td><td><code>web/src/features/bibliometrics/</code></td></tr><tr><td>Search draft and reusable model inputs</td><td><code>web/src/features/search/search-draft.ts</code>, <code>web/src/features/search/use-search-configuration.ts</code>, <code>web/src/features/settings/ConnectionSheet.vue</code></td></tr><tr><td>Review evidence and saved source graph</td><td><code>web/src/features/review/ReviewEvidence.vue</code></td></tr><tr><td>Shared settings contracts and validation</td><td><code>paperseek_app/settings.py</code></td></tr><tr><td>Connectivity checks</td><td><code>paperseek_app/settings_probes.py</code>, with deployment-supplied clients and sources</td></tr><tr><td>Structured review output and repair</td><td><code>paperseek_core/review/structured.py</code></td></tr><tr><td>Review evidence extraction and planning</td><td><code>paperseek_core/review/planning.py</code></td></tr><tr><td>Review section generation and checks</td><td><code>paperseek_core/review/generation.py</code>; shared instructions in <code>prompts.py</code></td></tr></tbody></table><p>Retrieval keeps metadata for already-returned pages before lane/fusion selection. The ranking inputs retain their existing bounds. A completed run writes a separate <code>bibliometric_corpus</code> artifact; result APIs and event streams do not carry the corpus. Community recovery checkpoints preserve it. The online edition&#39;s policy can skip checkpoints while still retaining the final corpus artifact.</p><p>Creating an analysis copies a compact corpus and overview into independent compressed files. SQL stores summaries, descriptors, and bounded network-cache references. Detail requests read the overview only; network computation and corpus export load the corpus on demand. Deletion first marks the record, then deletes files, then retains a minimal idempotency tombstone so late retries cannot recreate it. Adapters enforce ownership before any file descriptor is exposed to a use case.</p><p>Network limits are explicit in the core. API concurrency guards bound simultaneous expensive operations; the browser computes only layout in a worker. Large source payloads, abstracts, full result records, and model credentials are not duplicated into the compact corpus. Do not move heavy analysis into history listing or page-mount effects.</p><p>Saved searches and reviews have display titles separate from their question/topic and execution versions. Module history shares UI behavior, while each API keeps its own persistence rules. Unsaved key inputs stay in form memory. Saved connections and source keys are encrypted by <code>paperseek_community/workspace_settings.py</code>; <code>web/src/features/settings/store.ts</code> caches only their public metadata. Submitted runs receive separate encrypted credential copies. Account changes must reset drafts and owner-scoped settings and history. Restoring a past run never silently changes it to current service defaults.</p><p>Run <code>test_bibliometrics.py</code>, the retrieval-boundary/recovery contracts, import-boundary checks, frontend type checks, and the offline <code>web/tests/browser/shell.spec.ts</code>, <code>settings.spec.ts</code>, <code>records.spec.ts</code>, and <code>reviews.spec.ts</code> fixtures after relevant changes. The opt-in <code>backend/scripts/benchmark_bibliometrics.py</code> records synthetic 3,000/10,000-paper costs; it is not a remote server or browser latency benchmark.</p><h2 id="workspace-surfaces" tabindex="-1">Workspace surfaces <a class="header-anchor" href="#workspace-surfaces" aria-label="Permalink to &quot;Workspace surfaces&quot;">​</a></h2><p><code>web/src/features/workspace/WorkspaceShell.vue</code> owns the header, fully collapsible sidebar, mobile drawer, and main scroll surface. <code>Sidebar.vue</code> owns module navigation and history; <code>WorkspaceSettingsMenu.vue</code> owns the account menu. <code>WorkspacePreferences.vue</code> routes the Model APIs, Data sources, General, and User sections. <code>web/src/features/settings/SettingsModels.vue</code>, <code>ConnectionSheet.vue</code>, <code>SettingsSources.vue</code>, and <code>SettingsUser.vue</code> implement saved connections, source configuration, and data management. Model connection drafts are tested without saving; data-source dialog tests call <code>saveSource(false)</code> before probing, so a failed probe or cancelling the dialog does not roll back the saved key and options. Both dialogs also provide an explicit Save action; default selections save immediately. Search drafts select saved connection IDs. Global defaults do not replace a saved review&#39;s own model controls. <code>web/src/styles/ui.css</code> owns tokens and primitives; <code>web/src/styles/app.css</code> owns the shell and overlays. The online edition supplies account and history slots through the shared shell; it does not copy the shell.</p>',12)])])}const m=t(a,[["render",c]]);export{h as __pageData,m as default};
